        { n: 8, prompt: "Each station's pattern of flashes was listed on ___ so that sailors could identify it.", answer: "navigational charts", accept: ["charts"], explanation: "A frase relevante é 'which was listed on navigational charts'.", tip: "Copie a expressão tal como está no texto; 'charts' sozinho só é aceite se o limite o permitir e fizer sentido." },
        { n: 9, prompt: "The heaviest lenses floated in a bath of liquid ___ and could be turned easily.", answer: "mercury", accept: ["liquid mercury"], explanation: "O texto afirma que flutuavam 'in a bath of liquid mercury'.", tip: "A palavra 'liquid' já está no enunciado, logo a lacuna pede apenas o substantivo." },
        { n: 10, prompt: "In the twentieth century, ___ meant that resident keepers were no longer needed.", answer: "automation", accept: ["automation"], explanation: "A frase 'automation in the twentieth made resident staff unnecessary' fornece a resposta.", tip: "'Resident staff' no texto = 'resident keepers' no enunciado: reconheça o sinónimo para localizar a frase." }
